import * as React from "react";
import { cn } from "../lib/utils";

export interface CanvasFluidWaveProps {
  className?: string;
  waveColor?: string;
  speed?: number;
  amplitude?: number;
}

export function CanvasFluidWave({
  className,
  waveColor = "rgba(120, 119, 198, 0.25)",
  speed = 0.02,
  amplitude = 24,
}: CanvasFluidWaveProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const [reducedMotion, setReducedMotion] = React.useState(false);

  React.useEffect(() => {
    const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mediaQuery.matches);
    const handler = () => setReducedMotion(mediaQuery.matches);
    mediaQuery.addEventListener("change", handler);
    return () => mediaQuery.removeEventListener("change", handler);
  }, []);

  React.useEffect(() => {
    if (reducedMotion) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let animationFrameId: number;
    let step = 0;

    const resize = () => {
      canvas.width = canvas.parentElement?.clientWidth || 400;
      canvas.height = canvas.parentElement?.clientHeight || 200;
    };

    resize();
    window.addEventListener("resize", resize);

    const render = () => {
      step += speed;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      ctx.beginPath();
      ctx.moveTo(0, canvas.height / 2);

      for (let x = 0; x < canvas.width; x++) {
        const y =
          Math.sin(x * 0.01 + step) * amplitude +
          Math.sin(x * 0.02 + step * 1.5) * (amplitude * 0.5) +
          canvas.height / 2;
        ctx.lineTo(x, y);
      }

      ctx.lineTo(canvas.width, canvas.height);
      ctx.lineTo(0, canvas.height);
      ctx.closePath();

      ctx.fillStyle = waveColor;
      ctx.fill();

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener("resize", resize);
      cancelAnimationFrame(animationFrameId);
    };
  }, [speed, amplitude, waveColor, reducedMotion]);

  return (
    <div className={cn("relative overflow-hidden rounded-xl bg-card border border-border", className)}>
      {reducedMotion ? (
        // Static CSS gradient fallback when prefers-reduced-motion is requested
        <div
          className="absolute inset-0 bg-gradient-to-b from-transparent to-primary/10"
          aria-hidden="true"
        />
      ) : (
        <canvas
          ref={canvasRef}
          className="absolute inset-0 h-full w-full pointer-events-none"
          aria-hidden="true"
        />
      )}
      <div className="relative z-10 p-6">
        <h3 className="text-base font-semibold text-foreground">Canvas Fluid Wave</h3>
        <p className="mt-1 text-sm text-muted-foreground">
          Interactive fluid simulation with automatic reduced-motion accessibility fallbacks.
        </p>
      </div>
    </div>
  );
}

/**
 * @license MIT
 * @origin Dot Matrix UI (https://dotmatrix.dev)
 * @author Dot Matrix Team
 * @curated-by Machine-First Design Agent Wiki
 * Maintained under upstream open-source license terms.
 */

import * as React from "react";
import { cn } from "../lib/utils";

export interface DotMatrixLoaderProps {
  rows?: number;
  cols?: number;
  dotSize?: number;
  gap?: number;
  className?: string;
  label?: string;
}

export function DotMatrixLoader({
  rows = 5,
  cols = 5,
  dotSize = 6,
  gap = 6,
  className,
  label = "Loading content",
}: DotMatrixLoaderProps) {
  const [activeFrame, setActiveFrame] = React.useState(0);

  React.useEffect(() => {
    const mediaQuery = typeof window !== "undefined" ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;
    if (mediaQuery?.matches) return;

    const timer = setInterval(() => {
      setActiveFrame((prev) => (prev + 1) % (rows + cols));
    }, 120);
    return () => clearInterval(timer);
  }, [rows, cols]);

  return (
    <div
      role="status"
      aria-label={label}
      className={cn("inline-flex flex-col items-center justify-center p-4", className)}
    >
      <div
        className="grid"
        style={{
          gridTemplateColumns: `repeat(${cols}, ${dotSize}px)`,
          gap: `${gap}px`,
        }}
      >
        {Array.from({ length: rows * cols }).map((_, i) => {
          const r = Math.floor(i / cols);
          const c = i % cols;
          const distance = r + c;
          const isLit = (distance + activeFrame) % (rows + cols) < 3;

          return (
            <div
              key={i}
              style={{ width: dotSize, height: dotSize }}
              className={cn(
                "rounded-full transition-colors duration-150",
                isLit ? "bg-primary" : "bg-muted-foreground/20"
              )}
            />
          );
        })}
      </div>
      <span className="sr-only">{label}</span>
    </div>
  );
}

